using UnityEngine;

namespace Astrea.BattleActions;

[CreateAssetMenu(fileName = "VolatileReactionAction", menuName = "Data/Battle/Battle Actions/Orion/VolatileReaction Action")]
public class VolatileReactionAction : GainTwoEffectsAction
{
	[Header("Volatile Reaction Action")]
	[SerializeField]
	private DefaultEffectAction thirdEffectAction;

	public BattleAction ThirdEffectAction => thirdEffectAction;

	public override void CastTargetAmount(GameObject target, int amount, GameObject source)
	{
		base.CastTargetAmount(target, amount, source);
		thirdEffectAction.CastTargetAmount(target, amount, source);
	}
}
